import{_ as o,l as s,o as e,c as l,v as t,p as i,x as n,d as p,i as d,S as f}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"拜占庭将军","description":"","frontmatter":{"title":"拜占庭将军","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/byzantine-generals.md","filePath":"cs/byzantine-generals.md","lastUpdated":1789023840000}'),h={name:"cs/byzantine-generals.md"};function c(E,a,A,_,m,P){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="拜占庭将军" tabindex="-1">拜占庭将军 <a class="header-anchor" href="#拜占庭将军" aria-label="Permalink to &quot;拜占庭将军&quot;">​</a></h1><div class="epigraph"><p>口头消息下 $n\\gt 3f$ 才能让忠诚将军达成同一命令；书面（不可伪造签名）可降到 $n\\gt f$。撒谎比崩溃贵三倍。</p><footer>—— 据 Lamport, Shostak and Pease, The Byzantine Generals Problem, TOPLAS 1982；Pease, Shostak and Lamport, JACM 1980 整理</footer></div><p>上一课<a href="/cs/flp-impossibility">FLP</a>在崩溃下封死了异步确定共识。缺口是<strong>故障类升级</strong>：进程不但停，还会发矛盾消息。本课时间模型先按同步口头/书面协议讲经典下界，不把 PBFT 的视图更换提前写完。后课一致性模型假定复制机能偏离到哪一档。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若干将军要进攻或撤退，忠诚者必须同命令，且该命令若指挥官忠诚则等于其提议。\\(f\\) 个叛徒任意说话。口头消息：可撒谎、可对两人说不同话，但不可伪造第三者身份（或模型里不假设签名）。Lamport–Shostak–Pease：口头需要 \\(n\\gt 3f\\)，且给出递归 OM 算法。书面消息：签名不可伪造、不可抵赖，则 \\(n\\gt f\\) 足够（SM 算法）。</p><p>缺口不是故事，而是把<a href="/cs/failure-models">故障模型</a>里「拜占庭」变成可证的 \\(n\\) 与 \\(f\\) 关系。同步轮是本课假设：口头递归按轮展开。异步拜占庭还要另付 FLP 与认证信道的账，后课 PBFT。</p><p><span class="marginnote">1980 的 PSM 论文先给交互一致性；1982 的 BGP 把故事与 OM/SM 写清楚。口头 \\(3f\\) 下界用分区+撒谎构造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>OM(\\(f\\))：指挥官广播；每人把收到的值再当指挥官跑 OM(\\(f-1\\))；取多数。\\(f=0\\) 即直接投递。指数消息是经典代价；后续多项式协议（Dolev 等）本课点名。签名把「第三人说了什么」钉死，叛徒不能再分裂忠诚者的证据。</p>',9)),(e(),i(f,null,{default:n(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ORAL%5B%22%E5%8F%A3%E5%A4%B4%3A%20%E5%8F%AF%E5%AF%B9%E4%B8%A4%E5%A4%84%E8%AF%B4%E8%B0%8E%22%5D%20--%3E%20N3%5B%22n%20%3E%203f%22%5D%0A%20%20WRIT%5B%22%E4%B9%A6%E9%9D%A2%E7%AD%BE%E5%90%8D%22%5D%20--%3E%20N1%5B%22n%20%3E%20f%22%5D%0A%20%20ORAL%20--%3E%20OM%5B%22OM%20%E9%80%92%E5%BD%92%E5%A4%9A%E6%95%B0%22%5D%0A%20%20WRIT%20--%3E%20SM%5B%22SM%20%E8%BD%AC%E5%8F%91%E7%AD%BE%E5%90%8D%E9%93%BE%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>崩溃是拜占庭真子集：能抗 \\(f\\) 拜占庭则能抗 \\(f\\) 崩溃，但 \\(n\\) 预算按拜占庭花。认证信道（点对点不可伪造）介于口头与完全书面之间，后课 PBFT 用 MAC/法定人数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下界直觉：三个进程一个叛徒，口头时忠诚二人无法判断谁在撒谎，各自坚持己见。四人一叛徒可以多数。签名后叛徒不能冒充别人的命令，忠诚者能收集一致的证据链。</p><p>本课不把工作量证明当拜占庭将军的解：PoW 换了参与集合与同步假设，后课单独钉直觉。也不把「多数派投票选主」直接叫拜占庭容错：无认证的多数在撒谎下会被分裂投票骗。</p><p>与租约、检测器：拜占庭心跳无意义。怀疑名单不能当 OM 的输入；要用消息交叉验证。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 PBFT 三阶段，不引入权益证明。不把口头协议当数据中心默认——实践用签名或 TLS 会话。后课默认：崩溃预算 \\(n\\gt 2f\\)，口头拜占庭 \\(n\\gt 3f\\)，签名可降。一致性课先按崩溃复制讲，拜占庭状态机放到 PBFT。</p><p>时间与失败这一课序在此封口：故障类、时间档、钟、检测、租约、不可能、撒谎下界。下一单元从「读看起来像什么」开始，不再从零定义崩溃。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>口头拜占庭：\\(n\\gt 3f\\)，OM 递归；书面：\\(n\\gt f\\)。</li><li>崩溃预算不能直接拿到撒谎场景复用。</li><li>同步经典结果；异步拜占庭后课。</li><li>出处：Lamport, Shostak and Pease, TOPLAS 1982；Pease et al., JACM 1980。</li></ul>',10))])}const u=o(h,[["render",c]]);export{T as __pageData,u as default};
